INSERT INTO `chart_of_accounts` VALUES (1,'1010','Cash on Hand','asset',NULL,1,1,'Physical cash in cash registers, POS drawers, and office petty cash.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(2,'1020','Main Business Bank Account','asset',NULL,1,1,'Primary commercial bank account for company operations and wire transfers.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(3,'1030','Digital Wallets & MFS','asset',NULL,1,1,'Mobile Financial Services accounts (bKash, Nagad, Stripe, PayPal balances).','2026-09-05 01:03:03','2026-09-05 01:03:03'),(4,'1100','Accounts Receivable (A/R)','asset',NULL,1,1,'Outstanding dues owed by customers for orders fulfilled on credit or pending payment.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(5,'1200','Merchandise Inventory','asset',NULL,1,1,'Current valuation of unsold inventory stock held in warehouse (FIFO asset).','2026-09-05 01:03:03','2026-09-05 01:03:03'),(6,'1500','Equipment & Fixed Assets','asset',NULL,0,1,'Physical assets, computer systems, and store fixtures owned by the business.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(7,'2010','Accounts Payable (A/P)','liability',NULL,1,1,'Unpaid invoices and balances owed to vendors and suppliers for purchase orders.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(8,'2020','Customer Advances & Store Credit','liability',NULL,1,1,'Customer pre-payments, gift cards, and outstanding wallet credits.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(9,'2030','Sales Tax / VAT Payable','liability',NULL,1,1,'Taxes collected on customer sales awaiting remittance to tax authorities.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(10,'2040','Accrued Operational Liabilities','liability',NULL,0,1,'Accrued expenses, utilities, and wages incurred but not yet settled.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(11,'3010','Owner\'s Capital','equity',NULL,1,1,'Initial and ongoing capital invested into the business by owners.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(12,'3020','Retained Earnings','equity',NULL,1,1,'Cumulative net profit or loss retained in the business over fiscal periods.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(13,'4010','Online Sales Revenue','revenue',NULL,1,1,'Gross income earned from web storefront product sales.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(14,'4020','POS & In-Store Sales Revenue','revenue',NULL,1,1,'Gross income earned through retail POS counter registers.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(15,'4030','Shipping & Delivery Income','revenue',NULL,1,1,'Shipping fees billed to customers on fulfilled orders.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(16,'4090','Sales Discounts & Promotions','revenue',NULL,1,1,'Contra-revenue account tracking coupon vouchers and promotional discounts granted.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(17,'4095','Sales Returns & Refunds','revenue',NULL,1,1,'Contra-revenue account for customer order returns, chargebacks, and full refunds.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(18,'5010','Cost of Goods Sold - Online','cogs',NULL,1,1,'Direct inventory acquisition cost for goods sold via the online store.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(19,'5020','Cost of Goods Sold - POS','cogs',NULL,1,1,'Direct inventory acquisition cost for goods sold through POS registers.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(20,'5030','Inventory Shrinkage & Loss','cogs',NULL,0,1,'COGS write-down due to damaged items, expiration, or inventory variance.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(21,'6010','Rent & Facility Expense','expense',NULL,0,1,'Lease payments for office premises, retail store, and storage warehouses.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(22,'6020','Salaries & Staff Compensation','expense',NULL,0,1,'Staff payroll, bonuses, and contractual compensation.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(23,'6030','Marketing & Advertising','expense',NULL,0,1,'Digital ad spend, influencer marketing, sponsorships, and campaigns.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(24,'6040','Courier & Logistics Expense','expense',NULL,0,1,'Third-party delivery partners, fulfillment costs, and packaging supplies.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(25,'6050','Utilities, Electric & Internet','expense',NULL,0,1,'Electricity, high-speed internet, water, and building maintenance.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(26,'6060','Software & Technology Services','expense',NULL,0,1,'Cloud hosting, SaaS subscriptions, email APIs, and security tools.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(27,'6070','Payment Gateway & Banking Fees','expense',NULL,0,1,'Transaction fee deductions from payment processors and bank charges.','2026-09-05 01:03:03','2026-09-05 01:03:03'),(28,'6090','General & Miscellaneous Expenses','expense',NULL,0,1,'Other petty and unclassified operational expenses.','2026-09-05 01:03:03','2026-09-05 01:03:03');
